import {queryCurve} from './engine.js?v=2.1.0';
export function queryStatus(q,curve){const axis=q.given===curve.xName?'x':'y',values=curve.iterations.flatMap(it=>it[axis]);return q.diagnosticNotes?.some(n=>/outside|extrapolat/i.test(n))||q.input<Math.min(...values)||q.input>Math.max(...values)?'Outside reference domain':'Within reference domain';}
export function evaluatedQueryCurve(curve,q,operating){if(!curve||!q)return [];const axis=q.given===curve.xName?'x':'y',values=curve.iterations.flatMap(it=>it[axis]),lo=Math.min(q.input,...values),hi=Math.max(q.input,...values),inputs=[...new Set([q.input,...Array.from({length:81},(_,j)=>lo+(hi-lo)*j/80)])].sort((a,b)=>a-b);return inputs.flatMap(input=>{try{const output=queryCurve(curve,input,q.given,q.wanted,q.deps,operating.domainPolicy||'error',[],operating.interpolationMethod||'reference-first');return [q.given===curve.xName?[input,output]:[output,input]];}catch{return [];}});}
export function lossInspection(device,category){const integral=device.lossIntegrals?.[category],events=(device.trace||[]).filter(e=>e.category===category&&Number.isFinite(e.energy_J));return {category,integral,events,power:(device.waveformTrace||[]).filter(s=>Number.isFinite(s.lossPower_W?.[category])).map(s=>[s.time_s,s.lossPower_W[category]])};}
